import { NgModule } from '@angular/core';
import { RouterModule, Routes } from '@angular/router';

const routes: Routes = [
  { path: '', redirectTo: 'uploadmanager', pathMatch: 'full' },
  { path: 'uploadmanager/:id', loadComponent: () => import('../../components/upload/uploadmanager/uploadmanager.component').then(m => m.UploadmanagerComponent) },
  { path: 'uploadreport/:id', loadComponent: () => import('../../components/upload/uploadreport/uploadreport.component').then(m => m.UploadreportComponent) },
  
]

@NgModule({
  imports: [RouterModule.forChild(routes)],
  exports: [RouterModule]
})
export class UploadmanagerRoutingModule { }
